pub fn UsingAArch32() -> bool {
    let aarch32: bool = g_PSTATE().nRW == 0b1;
    if !HaveAArch64() {
        assert!(aarch32);
    }
    aarch32
}

pub fn AdvSIMDExpandImm(op: u8, cmode: u8, imm8: u8) -> u64 {
    let mut imm64: u64 = Default::default();
    match cmode >> 1 {
        0b000 => {
            imm64 = asl::Replicate_64_32(imm8 as u32);
        }
        0b001 => {
            imm64 = asl::Replicate_64_32((imm8 as u32) << 8);
        }
        0b010 => {
            imm64 = asl::Replicate_64_32((imm8 as u32) << 16);
        }
        0b011 => {
            imm64 = asl::Replicate_64_32((imm8 as u32) << 24);
        }
        0b100 => {
            imm64 = asl::Replicate_64_16(imm8 as u16);
        }
        0b101 => {
            imm64 = asl::Replicate_64_16((imm8 as u16) << 8);
        }
        0b110 => {
            if cmode & 0x1 == 0b0 {
                imm64 = asl::Replicate_64_32((imm8 as u32) << 8 | 0b11111111_u32);
            } else {
                imm64 = asl::Replicate_64_32((imm8 as u32) << 16 | 0xffff_u32);
            }
        }
        _ => {
            if cmode & 0x1 == 0b0 && op == 0b0 {
                imm64 = asl::Replicate_64_8(imm8);
            }
            if cmode & 0x1 == 0b0 && op == 0b1 {
                let imm8a: u8 = asl::Replicate_8_1(imm8 >> 7);
                let imm8b: u8 = asl::Replicate_8_1((imm8 >> 6) & 0x1);
                let imm8c: u8 = asl::Replicate_8_1((imm8 >> 5) & 0x1);
                let imm8d: u8 = asl::Replicate_8_1((imm8 >> 4) & 0x1);
                let imm8e: u8 = asl::Replicate_8_1((imm8 >> 3) & 0x1);
                let imm8f: u8 = asl::Replicate_8_1((imm8 >> 2) & 0x1);
                let imm8g: u8 = asl::Replicate_8_1((imm8 >> 1) & 0x1);
                let imm8h: u8 = asl::Replicate_8_1(imm8 & 0x1);
                imm64 = (imm8a as u64) << 56
                    | (imm8b as u64) << 48
                    | (imm8c as u64) << 40
                    | (imm8d as u64) << 32
                    | (imm8e as u64) << 24
                    | (imm8f as u64) << 16
                    | (imm8g as u64) << 8
                    | imm8h as u64;
            }
            if cmode & 0x1 == 0b1 && op == 0b0 {
                let imm32: u32 = ((imm8 >> 7) as u32) << 31
                    | ((!((imm8 >> 6) & 0x1) & 0x1) as u32) << 30
                    | (asl::Replicate_5_1((imm8 >> 6) & 0x1) as u32) << 25
                    | ((imm8 & 0x3f) as u32) << 19;
                imm64 = asl::Replicate_64_32(imm32);
            }
            if cmode & 0x1 == 0b1 && op == 0b1 {
                if UsingAArch32() {
                    impdef::ReservedEncoding();
                }
                imm64 = ((imm8 >> 7) as u64) << 63
                    | ((!((imm8 >> 6) & 0x1) & 0x1) as u64) << 62
                    | (asl::Replicate_8_1((imm8 >> 6) & 0x1) as u64) << 54
                    | ((imm8 & 0x3f) as u64) << 48;
            }
        }
    }
    imm64
}

pub fn DecodeBitMasks_32(
    immN: u8,
    imms: u8,
    immr: u8,
    immediate: bool,
) -> Result<(u32, u32), DecodeError> {
    if (immN << 6 | (!imms & 0x3f)) & 0x7e == 0x0 {
        shadow::Undefined()?;
    }
    let len: u8 = (immN << 6 | (!imms & 0x3f)).ilog2() as u8;
    assert!(2 <= 2_i128.pow(len as u32) && 2_i128.pow(len as u32) <= 32);
    let levels: u8 = ((1u128 << len) - 1) as u8;
    if immediate && imms & levels == levels {
        shadow::Undefined()?;
    }
    let s: u8 = imms & levels;
    let r: u8 = immr & levels;
    let diff = s as i128 - r as i128;
    let esize: u8 = 1 << len;
    let d = diff & ((1_i128 << len) - 1);
    let welem: u128 = asl::ZeroExtend(esize as i128, s as i128 + 1, (1u128 << (s + 1)) - 1);
    let telem: u128 = asl::ZeroExtend(esize as i128, d + 1, (1u128 << (d + 1)) - 1);
    let wmask: u32 =
        asl::Replicate(32, esize as i128, asl::ROR(esize as i128, welem, r as i128)) as u32;
    let tmask: u32 = asl::Replicate(32, esize as i128, telem) as u32;
    Ok((wmask, tmask))
}

