pub fn VFPExpandImm_16(imm8: u8) -> u16 {
    let sign: u8 = imm8 >> 7;
    let exp: u8 = (!((imm8 >> 6) & 0x1) & 0x1) << 4
        | asl::Replicate_2_1((imm8 >> 6) & 0x1) << 2
        | (imm8 >> 4) & 0x3;
    let frac: u16 = ((imm8 & 0xf) as u16) << 6;
    let result: u16 = (sign as u16) << 15 | (exp as u16) << 10 | frac;
    result
}

pub fn VFPExpandImm_32(imm8: u8) -> u32 {
    let sign: u8 = imm8 >> 7;
    let exp: u8 = (!((imm8 >> 6) & 0x1) & 0x1) << 7
        | asl::Replicate_5_1((imm8 >> 6) & 0x1) << 2
        | (imm8 >> 4) & 0x3;
    let frac: u32 = ((imm8 & 0xf) as u32) << 19;
    let result: u32 = (sign as u32) << 31 | (exp as u32) << 23 | frac;
    result
}

pub fn VFPExpandImm_64(imm8: u8) -> u64 {
    let sign: u8 = imm8 >> 7;
    let exp: u16 = ((!((imm8 >> 6) & 0x1) & 0x1) as u16) << 10
        | (asl::Replicate_8_1((imm8 >> 6) & 0x1) as u16) << 2
        | ((imm8 >> 4) & 0x3) as u16;
    let frac: u64 = ((imm8 & 0xf) as u64) << 48;
    let result: u64 = (sign as u64) << 63 | (exp as u64) << 52 | frac;
    result
}
